// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListConnections Every connection with its last-opened time and unlock state
	// (GET /connections)
	ListConnections(ctx context.Context, request ListConnectionsRequestObject) (ListConnectionsResponseObject, error)
	// CreateConnection Create a connection and store its secret
	// (POST /connections)
	CreateConnection(ctx context.Context, request CreateConnectionRequestObject) (CreateConnectionResponseObject, error)
	// TestConnection Open a short-lived session with the given settings and report the server
	// (POST /connections/test)
	TestConnection(ctx context.Context, request TestConnectionRequestObject) (TestConnectionResponseObject, error)

	// (DELETE /connections/{connectionId})
	DeleteConnection(ctx context.Context, request DeleteConnectionRequestObject) (DeleteConnectionResponseObject, error)

	// (GET /connections/{connectionId})
	GetConnection(ctx context.Context, request GetConnectionRequestObject) (GetConnectionResponseObject, error)
	// UpdateConnection Update settings; the secret changes only when given
	// (PUT /connections/{connectionId})
	UpdateConnection(ctx context.Context, request UpdateConnectionRequestObject) (UpdateConnectionResponseObject, error)
	// ListAudit Writes Mesa ran on this connection, newest first
	// (GET /connections/{connectionId}/audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)

	// (GET /connections/{connectionId}/databases)
	ListDatabases(ctx context.Context, request ListDatabasesRequestObject) (ListDatabasesResponseObject, error)
	// CreateDatabase Create an empty database (a reviewed write)
	// (POST /connections/{connectionId}/databases)
	CreateDatabase(ctx context.Context, request CreateDatabaseRequestObject) (CreateDatabaseResponseObject, error)
	// ApplyChanges Run a change set after policy approves it
	// (POST /connections/{connectionId}/databases/{database}/changes/apply)
	ApplyChanges(ctx context.Context, request ApplyChangesRequestObject) (ApplyChangesResponseObject, error)
	// PlanChanges Compile a change set into SQL, risks and the policy decision
	// (POST /connections/{connectionId}/databases/{database}/changes/plan)
	PlanChanges(ctx context.Context, request PlanChangesRequestObject) (PlanChangesResponseObject, error)
	// PlanScript Plan a hand-written SQL script as a change (statements, risks, policy decision)
	// (POST /connections/{connectionId}/databases/{database}/changes/script)
	PlanScript(ctx context.Context, request PlanScriptRequestObject) (PlanScriptResponseObject, error)
	// ApplyScript Run a hand-written SQL script after policy approves it; audited like every write
	// (POST /connections/{connectionId}/databases/{database}/changes/script/apply)
	ApplyScript(ctx context.Context, request ApplyScriptRequestObject) (ApplyScriptResponseObject, error)
	// GetDesignerModel The live schema as a model, its DBML and the saved diagram layout
	// (GET /connections/{connectionId}/databases/{database}/designer)
	GetDesignerModel(ctx context.Context, request GetDesignerModelRequestObject) (GetDesignerModelResponseObject, error)
	// DiffDesignerModel Changes between the live schema and the edited model, planned as SQL
	// (POST /connections/{connectionId}/databases/{database}/designer/diff)
	DiffDesignerModel(ctx context.Context, request DiffDesignerModelRequestObject) (DiffDesignerModelResponseObject, error)

	// (PUT /connections/{connectionId}/databases/{database}/designer/layout)
	SaveDesignerLayout(ctx context.Context, request SaveDesignerLayoutRequestObject) (SaveDesignerLayoutResponseObject, error)

	// (POST /connections/{connectionId}/databases/{database}/explain)
	ExplainQuery(ctx context.Context, request ExplainQueryRequestObject) (ExplainQueryResponseObject, error)

	// (GET /connections/{connectionId}/databases/{database}/monitor/overview)
	GetMonitorOverview(ctx context.Context, request GetMonitorOverviewRequestObject) (GetMonitorOverviewResponseObject, error)
	// GetEnginePanel The engine-specific metrics panel
	// (GET /connections/{connectionId}/databases/{database}/monitor/panel)
	GetEnginePanel(ctx context.Context, request GetEnginePanelRequestObject) (GetEnginePanelResponseObject, error)

	// (GET /connections/{connectionId}/databases/{database}/monitor/sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// KillSession Cancel the running query, or terminate the backend
	// (POST /connections/{connectionId}/databases/{database}/monitor/sessions/{pid}/kill)
	KillSession(ctx context.Context, request KillSessionRequestObject) (KillSessionResponseObject, error)
	// GetMonitorSnapshot Current metrics, rates since the previous sample and the recent series
	// (GET /connections/{connectionId}/databases/{database}/monitor/snapshot)
	GetMonitorSnapshot(ctx context.Context, request GetMonitorSnapshotRequestObject) (GetMonitorSnapshotResponseObject, error)
	// RunQuery Run SQL in a read-only transaction; writes go through changes/script
	// (POST /connections/{connectionId}/databases/{database}/query)
	RunQuery(ctx context.Context, request RunQueryRequestObject) (RunQueryResponseObject, error)
	// QueryRows Page through a table with filters and sort
	// (POST /connections/{connectionId}/databases/{database}/rows)
	QueryRows(ctx context.Context, request QueryRowsRequestObject) (QueryRowsResponseObject, error)
	// GetSchema The full model of the database, with stats
	// (GET /connections/{connectionId}/databases/{database}/schema)
	GetSchema(ctx context.Context, request GetSchemaRequestObject) (GetSchemaResponseObject, error)
	// GetTable One table with fresh stats
	// (GET /connections/{connectionId}/databases/{database}/tables/{schema}/{table})
	GetTable(ctx context.Context, request GetTableRequestObject) (GetTableResponseObject, error)

	// (GET /connections/{connectionId}/history)
	ListHistory(ctx context.Context, request ListHistoryRequestObject) (ListHistoryResponseObject, error)
	// PingConnection Round trip to the server with the stored secret
	// (POST /connections/{connectionId}/ping)
	PingConnection(ctx context.Context, request PingConnectionRequestObject) (PingConnectionResponseObject, error)

	// (GET /connections/{connectionId}/roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// CreateRole Create a role (a reviewed write)
	// (POST /connections/{connectionId}/roles)
	CreateRole(ctx context.Context, request CreateRoleRequestObject) (CreateRoleResponseObject, error)
	// DropRole Drop a role (a reviewed write)
	// (DELETE /connections/{connectionId}/roles/{role})
	DropRole(ctx context.Context, request DropRoleRequestObject) (DropRoleResponseObject, error)
	// LockConnection End the unlock early
	// (DELETE /connections/{connectionId}/unlock)
	LockConnection(ctx context.Context, request LockConnectionRequestObject) (LockConnectionResponseObject, error)
	// UnlockConnection Allow writes on a read-only connection for a while
	// (POST /connections/{connectionId}/unlock)
	UnlockConnection(ctx context.Context, request UnlockConnectionRequestObject) (UnlockConnectionResponseObject, error)
	// ParseDbml Parse DBML into a model (stateless)
	// (POST /designer/parse)
	ParseDbml(ctx context.Context, request ParseDbmlRequestObject) (ParseDbmlResponseObject, error)
	// PrintDbml Print a model as DBML (stateless)
	// (POST /designer/print)
	PrintDbml(ctx context.Context, request PrintDbmlRequestObject) (PrintDbmlResponseObject, error)

	// (GET /queries)
	ListSavedQueries(ctx context.Context, request ListSavedQueriesRequestObject) (ListSavedQueriesResponseObject, error)
	// SaveQuery Create or update a saved query (by id)
	// (PUT /queries)
	SaveQuery(ctx context.Context, request SaveQueryRequestObject) (SaveQueryResponseObject, error)

	// (DELETE /queries/{queryId})
	DeleteSavedQuery(ctx context.Context, request DeleteSavedQueryRequestObject) (DeleteSavedQueryResponseObject, error)
	// GetSystemInfo Version, mode and capabilities of this Mesa
	// (GET /system/info)
	GetSystemInfo(ctx context.Context, request GetSystemInfoRequestObject) (GetSystemInfoResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListConnections operation middleware
func (sh *strictHandler) ListConnections(w http.ResponseWriter, r *http.Request) {
	var request ListConnectionsRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListConnections(ctx, request.(ListConnectionsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListConnections")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListConnectionsResponseObject); ok {
		if err := validResponse.VisitListConnectionsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

